import { Button as BaseButton } from "@base-ui/react/button";

import type { ButtonProps as ButtonProperties } from "./types";
import { buttonClassName } from "./styles";

export type { ButtonProps, ButtonVariant } from "./types";

/**
 * MC 石纹按钮（规格 §4 #1）：原版 20 GUI px 高。
 * 悬浮 / 聚焦 / 禁用态由 textures.css 伪类切换，无 JS 状态，SSR 安全。
 */
export function Button({ className, variant, ...properties }: ButtonProperties) {
  return (
    <BaseButton
      className={buttonClassName({ className, variant })}
      type="button"
      {...properties}
    />
  );
}

import { cva } from "class-variance-authority";

import type { ButtonProps as ButtonProperties } from "./types";

import { cn } from "@/components/tennantite/lib/tennantite-utils";

/**
 * 原版按钮几何：200×20 GUI px，横向内边距 4 GUI px；
 * 悬浮 / 聚焦态的白色边框与填充变化由 textures.css 的伪类接管。
 */
export const buttonStyles = cva(
  [
    "mc-text-shadow inline-flex h-20 max-w-full cursor-pointer items-center justify-center gap-0 overflow-hidden px-4",
    "font-mc mc-text text-mc-text-main no-underline select-none",
    "whitespace-nowrap",
    "disabled:cursor-not-allowed disabled:text-mc-text-dim",
  ].join(" "),
  {
    defaultVariants: {
      variant: "default",
    },
    variants: {
      variant: {
        default: "mc-tex-btn",
        ghost: [
          "bg-transparent",
          "hover:bg-white/10 active:bg-white/20",
          "focus-visible:mc-outline focus-visible:outline-white",
        ].join(" "),
        realms: "mc-tex-btn-realms focus-visible:mc-outline focus-visible:outline-white",
        success: "mc-tex-btn-success focus-visible:mc-outline focus-visible:outline-white",
      },
    },
  },
);

export function buttonClassName({
  className,
  variant,
}: Pick<ButtonProperties, "className" | "variant">): string {
  return cn(buttonStyles({ variant }), className);
}

import type { ComponentProps } from "react";

export interface ButtonProps extends ComponentProps<"button"> {
  /**
  * 视觉变体：default 石纹（规格 §4 #1）/ success 主行动绿 / ghost 透明
  */
  variant?: ButtonVariant;
}

export type ButtonVariant = "default" | "ghost" | "realms" | "success";
